88: }: WalletConnectSignTransactionParams): Promise<ResultSuccess> =>
89: 	execute({
90: 		params,
91: 		callback: async ({
92: 			request,
93: 			listener
94: 		}: WalletConnectCallBackParams): Promise<
95: 			ResultSuccess & {
96: 				amount?: bigint;
97: 				destination?: SolAddress;
98: 			}
99: 		> => {
100: 			const {
101: 				id,
102: 				topic,
103: 				params: {
104: 					request: {
105: 						method,
106: 						params: { transaction: base64EncodedTransactionMessage }
107: 					}
108: 				}
109: 			} = request;
110: 
111: 			const {
112: 				network: { id: networkId }
113: 			} = token;
114: 
115: 			if (isNullish(address)) {
116: 				toastsError({
117: 					msg: { text: get(i18n).wallet_connect.error.wallet_not_initialized }
118: 				});
119: 				return { success: false };
120: 			}
121: 
122: 			const solNetwork = mapNetworkIdToNetwork(networkId);
123: 
124: 			assertNonNullish(
125: 				solNetwork,
126: 				replacePlaceholders(get(i18n).init.error.no_solana_network, {
127: 					$network: networkId.description ?? ''
128: 				})
129: 			);
130: 
131: 			const parsedTransactionMessage = await parseSolBase64TransactionMessage({
132: 				transactionMessage: base64EncodedTransactionMessage,
133: 				rpc: solanaHttpRpc(solNetwork)
134: 			});
135: 
136: 			const { amount, destination } = mapSolTransactionMessage(parsedTransactionMessage);
137: 
138: 			// TODO: add assertions checks about amount, payer, source and destination when we will able to properly parse them for ALL the transactions
139: 
140: 			modalNext();
141: 
142: 			try {
143: 				progress(ProgressStepsSign.SIGN);
144: 
145: 				assertNonNullish(address);
146: 
147: 				const rpc = solanaHttpRpc(solNetwork);
148: 
149: 				const signer = createSigner({
150: 					identity,
151: 					address,
152: 					network: solNetwork
153: 				});
154: 
155: 				const transactionMessageRaw = await parseSolBase64TransactionMessage({
156: 					transactionMessage: base64EncodedTransactionMessage,
157: 					rpc
158: 				});
159: 
160: 				// It should not happen, since we receive transaction with blockhash lifetime, but just to guarantee the correct type casting
161: 				if (!transactionMessageHasBlockhashLifetime(transactionMessageRaw)) {
162: 					return { success: false };
163: 				}
164: 
165: 				const { signatures } = decodeTransactionMessage(base64EncodedTransactionMessage);
166: 				const additionalSigners = Object.keys(signatures)
167: 					.filter((a) => a !== address)
168: 					.map((signer) =>
169: 						createSigner({
170: 							identity,
171: 							address: signer,
172: 							network: solNetwork
173: 						})
174: 					);
175: 				const transactionMessageWithAllSigners = addSignersToTransactionMessage(
176: 					additionalSigners,
177: 					transactionMessageRaw
178: 				);
179: 
180: 				const transactionMessage = await setLifetimeAndFeePayerToTransaction({
181: 					transactionMessage: transactionMessageWithAllSigners,
182: 					rpc,
183: 					feePayer: signer
184: 				});
185: 
186: 				const { signedTransaction, signature } = await signTransaction(transactionMessage);
187: 
188: 				const transactionBytes = getBase64Decoder().decode(
189: 					getTransactionEncoder().encode(signedTransaction)
190: 				);
191: 
192: 				const { simulateTransaction } = rpc;
193: 
194: 				const simulationResult = await simulateTransaction(
195: 					transactionBytes as Base64EncodedWireTransaction,
196: 					{
197: 						encoding: 'base64'
198: 					}
199: 				).send();
200: 
201: 				if (nonNullish(simulationResult.value.err)) {
202: 					// In case of simulation error, it is useful to log the error to the console for development purposes
203: 					console.warn('WalletConnect Solana transaction simulation error', simulationResult);
204: 				}
205: 
206: 				if (method === SESSION_REQUEST_SOL_SIGN_AND_SEND_TRANSACTION) {
207: 					progress(ProgressStepsSendSol.SEND);
208: 				}
209: 
210: 				try {
211: 					// Even if some DEXs send an only-sign transaction, they do not send it when we return it.
212: 					// So, for good measure, we will send it anyway. It is not an issue if it is sent twice, since only one will pass.
213: 					// Plus, if it requires more signatures on the DEX's side, it will be sent again by them and it will fail with us.
214: 					sendSignedTransaction({
215: 						rpc,
216: 						rpcSubscriptions: solanaWebSocketRpc(solNetwork),
217: 						signedTransaction
218: 					});
219: 				} catch (err: unknown) {
220: 					// If the transaction requires that we send it, and it fails, we reject the request, otherwise we just log the error
221: 					if (method !== SESSION_REQUEST_SOL_SIGN_AND_SEND_TRANSACTION) {
222: 						console.warn('WalletConnect Solana transaction send error', err);
223: 					}
224: 				}
225: 
226: 				progress(ProgressStepsSign.APPROVE_WALLET_CONNECT);
227: 
228: 				await listener.approveRequest({
229: 					id,
230: 					topic,
231: 					message: { signature }
232: 				});
233: 
234: 				progress(ProgressStepsSign.DONE);
235: 
236: 				trackEvent({
237: 					name: TRACK_COUNT_WC_SOL_SEND_SUCCESS,
238: 					metadata: {
239: 						token: token.symbol
240: 					}
241: 				});
242: 
243: 				return { success: true, amount, destination };
244: 			} catch (err: unknown) {
245: 				trackEvent({
246: 					name: TRACK_COUNT_WC_SOL_SEND_ERROR,
247: 					metadata: {
248: 						token: token.symbol
249: 					}
250: 				});
251: 
252: 				await listener.rejectRequest({ topic, id, error: UNEXPECTED_ERROR });
253: 
254: 				throw err;
255: 			}
256: 		},
257: 		toastMsg: replacePlaceholders(get(i18n).wallet_connect.info.sol_transaction_executed, {
258: 			$method: params.request.params.request.method
259: 		})
260: 	});

